function tilePattern(t){let n=t%9+1;const layouts={1:[[20,28]],2:[[20,14],[20,42]],3:[[10,12],[20,28],[30,44]],4:[[10,14],[30,14],[10,42],[30,42]],5:[[10,12],[30,12],[20,28],[10,44],[30,44]],6:[[10,12],[30,12],[10,28],[30,28],[10,44],[30,44]],7:[[9,9],[20,16],[31,23],[10,36],[30,36],[10,48],[30,48]],8:[[10,8],[30,8],[10,21],[30,21],[10,35],[30,35],[10,48],[30,48]],9:[[9,10],[20,10],[31,10],[9,28],[20,28],[31,28],[9,46],[20,46],[31,46]]};let shapes='';if(t<18){shapes=layouts[n].map(([x,y],k)=>{let r=n===1?14:n>=7?4.5:6,c=n===1?'#287354':n===5&&k===2||n===9&&k>=3&&k<6?'#b0443c':n===7&&k<3?'#b0443c':'#315976';return `<g class="pip" fill="none" stroke="${c}"><circle cx="${x}" cy="${y}" r="${r}" stroke-width="${n===1?3:1.7}"/><circle cx="${x}" cy="${y}" r="${r*.48}" stroke-width="1"/><circle cx="${x}" cy="${y}" r="1" fill="${c}"/></g>`}).join('')}else if(n===1){shapes='<g class="bamboo-bird"><path d="M21 30Q10 34 8 48L17 43L14 51Q28 45 28 32" fill="#27734d"/><path d="M16 18Q17 9 24 9Q30 10 28 17L24 23Q33 30 27 37Q14 40 13 29Q12 23 16 18" fill="#358666"/><path d="M18 24Q30 29 23 35Q15 36 17 29" fill="#294e75"/><path d="M27 12L35 16L27 17" fill="#bd5142"/><circle cx="24" cy="12" r="1.4" fill="#fff"/><path d="M19 8L17 4M22 8L22 3" stroke="#b94740" stroke-width="2"/><path d="M22 37L24 44L29 44M18 38L18 46L22 46" fill="none" stroke="#9b633b" stroke-width="1.7"/></g>'}else{let positions=n===3?[[20,10],[10,38],[30,38]]:n===7?[[20,7],[10,23],[30,23],[10,35],[30,35],[10,47],[30,47]]:layouts[n];shapes=positions.map(([x,y],k)=>`<g class="bamboo-stick" stroke="${n===5&&k===2||n===9&&k<3?'#b14d41':'#28704d'}" stroke-linecap="round"><path d="M${x-1.5} ${y-5}V${y+5}M${x+1.5} ${y-5}V${y+5}" stroke-width="2"/><path d="M${x-3} ${y-4}H${x+3}M${x-3} ${y}H${x+3}M${x-3} ${y+4}H${x+3}" stroke-width="1.5"/></g>`).join('')}return '<svg class="tile-art" viewBox="0 0 40 56" aria-hidden="true" focusable="false">'+shapes+'</svg>'}
